import{_ as o,o as t,c as a,a5 as d}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"HJ75 公共子串计算","description":"中等 通过率：36.30% 时间限制：1秒 空间限制：32M 知识点 字符串 查找 动态规划 描述 给定两个只包含小写字母的字符串，计算两个字符串的最大公共子串的长度。 注：子串的定义指一个字符串删掉其部分前缀和后缀（也可以不删）后形成的字符串。 数据范围：字符串长度：0 1≤。","frontmatter":{"title":"HJ75 公共子串计算","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：36.30% 时间限制：1秒 空间限制：32M 知识点 字符串 查找 动态规划 描述 给定两个只包含小写字母的字符串，计算两个字符串的最大公共子串的长度。 注：子串的定义指一个字符串删掉其部分前缀和后缀（也可以不删）后形成的字符串。 数据范围：字符串长度：0 1≤。","sidebarWeight":22,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/动态规划【中等】/HJ75 公共子串计算.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ75 公共子串计算.md","filePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ75 公共子串计算.md"}'),s={name:"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ75 公共子串计算.md"};function r(n,e,c,i,p,_){return t(),a("div",null,[...e[0]||(e[0]=[d('<div><h1 id="hj75-公共子串计算" tabindex="-1">HJ75 公共子串计算 <a class="header-anchor" href="#hj75-公共子串计算" aria-label="Permalink to &quot;HJ75 公共子串计算&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ75 公共子串计算”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：36.30% 时间限制：1秒 空间限制：32M 知识点 ==字符串====查找====动态规划== <strong>描述</strong> 给定两个只包含小写字母的字符串，计算两个字符串的最大公共子串的长度。 注：子串的定义指一个字符串删掉其部分前缀和后缀（也可以不删）后形成的字符串。 数据范围：字符串长度：0 1≤<em>s</em>≤150 进阶：时间复杂度：<em>O</em>(_n_3) ，空间复杂度： <em>O</em>(<em>n</em>) <strong>输入描述：</strong> 输入两个只包含小写字母的字符串 <strong>输出描述：</strong> 输出一个整数，代表最大公共子串的长度 <strong>示例1</strong> 输入： asdfaswerasdfaswer ==复制== 输出： 6 ==复制==</p></blockquote><p>为了解决这个问题，我们可以使用动态规划的方法。动态规划是一种通过把原问题分解为相对简单的子问题的方式来求解复杂问题的方法。</p><p>这个问题中，我们定义一个二维数组<code>dp</code>，其中<code>dp[i][j]</code>代表以第一个字符串中第<code>i</code>个字符结尾和第二个字符串中第<code>j</code>个字符结尾的最大公共子串的长度。初始时，<code>dp[i][j]</code>都为0。</p><p>然后，我们遍历两个字符串，当发现两个字符相同时，我们就更新<code>dp[i][j]</code>为<code>dp[i-1][j-1] + 1</code>，即在之前最大公共子串长度的基础上加1。如果字符不相同，则<code>dp[i][j]</code>保持为0，因为以这两个字符结尾的子串不可能是公共子串。</p><p>遍历完成后，数组<code>dp</code>中的最大值即为最大公共子串的长度。</p><p>下面是Python代码实现： def max_common_substring_length(str1, str2): n = len(str1) m = len(str2) dp = [[0] * (m + 1) for _ in range(n + 1)] max_length = 0 for i in range(1, n + 1): for j in range(1, m + 1): if str1[i - 1] == str2[j - 1]: dp[i][j] = dp[i - 1][j - 1] + 1 max_length = max(max_length, dp[i][j]) return max_length</p><h1 id="测试代码" tabindex="-1">测试代码 <a class="header-anchor" href="#测试代码" aria-label="Permalink to &quot;测试代码&quot;">​</a></h1><p>str1 = &quot;asdfas&quot; str2 = &quot;werasdfaswer&quot; print(max_common_substring_length(str1, str2))</p><p>这段代码定义了一个函数<code>max_common_substring_length</code>，它接收两个字符串作为参数，计算它们的最大公共子串的长度，并返回这个长度。这个实现的时间复杂度为<code>O(n*m)</code>，空间复杂度为<code>O(n*m)</code>，其中<code>n</code>和<code>m</code>分别是输入字符串的长度。</p></div>',1)])])}const g=o(s,[["render",r]]);export{l as __pageData,g as default};
